import{z as p,x as d,o as l,c as A,q as o,j as t,D as e,d as r,s as n,S as E,b as i}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"PIR","description":"","frontmatter":{"title":"PIR","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/pir.md","filePath":"cs/pir.md","lastUpdated":1791413859000}'),B={name:"cs/pir.md"};function u(_,a,D,C,m,P){const s=d("Mermaid");return l(),A("div",null,[a[2]||(a[2]=o('<h1 id="pir" tabindex="-1">PIR <a class="header-anchor" href="#pir" aria-label="Permalink to &quot;PIR&quot;">​</a></h1><div class="epigraph"><p>私有信息检索让用户从服务器取第 i 条，而不让服务器知道 i。信息论 PIR 要多服务器；计算 PIR 用同态，更重。索引隐私与内容保密不是同一句话。</p><footer>—— Chor, Goldreich, Kushilevitz and Sudan, Private Information Retrieval, JACM 1998</footer></div><p>上一课<a href="/cs/mpc-applications">MPC</a>是多方表。缺口是<strong>单用户对数据库的查询隐私</strong>。本课 PIR 直觉。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>HTTPS 加密传输，却仍让服务器看见 URL 或索引——被保密的是内容，不是「你查了哪一条」。PIR 的合同是服务器答对第 \\(i\\) 条却推不出 \\(i\\)。缺口随之有两个：私有查询要付多少通信膨胀，以及恶意服务器返回假答案时用户能否察觉。</p><h3 id="不是匿名网" tabindex="-1">不是匿名网 <a class="header-anchor" href="#不是匿名网" aria-label="Permalink to &quot;不是匿名网&quot;">​</a></h3><p>PIR 不藏网络身份；Tor 后课管路由。</p><p><span class="marginnote">CGKS 1998。Tor 下一课。</span></p><p><span class="marginnote">「内容保密、查询不保密」的直观版：加密快递盒没人看得见里面是什么，但快递单上明晃晃写着你去取的是哪个柜子、几点取的。PIR 要办的事就是把「取的哪一格」这一行也从单子上抹掉。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>平凡解是下载全集：隐私完美，通信 \\(O(n)\\)，大库上不可行。方法因此是拿协议换通信：多服务器方向把独热向量拆成随机份额，让每台单独看都一无所知。下一课 Tor。</p>',12)),(l(),t(E,null,{default:e(()=>[n(s,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20I%5B%22%E7%B4%A2%E5%BC%95%20i%22%5D%20--%3E%20PIR%5B%22%E6%A3%80%E7%B4%A2%E5%8D%8F%E8%AE%AE%22%5D%0A%20%20PIR%20--%3E%20REC%5B%22%E8%AE%B0%E5%BD%95%22%5D%0A%20%20SRV%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%22%5D%20-.-%3E%7C%22%E4%B8%8D%E7%9F%A5%20i%22%7C%20PIR%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=i("h2",{id:"机制",tabindex:"-1"},[r("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=i("p",null,"两台服务器就能把「取第 \\(i\\) 条」拆成不可识别的查询份额。设数据库是 \\(n\\) 个比特 \\(D_0,\\dots,D_{n-1}\\)，两台服务器各存同一份。用户先抽均匀随机集合 \\(S\\subseteq[n]\\)，把独热指示向量 \\(e_i\\) 用一次性掩码拆成两个查询份额：服务器 0 收到 \\(S\\)，服务器 1 收到 \\(S\\oplus\\{i\\}\\)。两台各自返回所收集合内全部条目的异或和：",-1)),a[5]||(a[5]=r(" \\[X_0=\\bigoplus_{j\\in S}D_j,\\qquad X_1=\\bigoplus_{j\\in S\\oplus\\{i\\}}D_j. \\]",-1)),a[6]||(a[6]=i("p",null,"用户本地计算 \\(X_0\\oplus X_1\\)：两个集合的对称差恰为 \\(\\{i\\}\\)，其余下标在两个和里成对出现、异或抵消，只剩 \\(D_i\\)。查询隐私在信息论意义成立：每台服务器看到的查询都是均匀随机集合，与 \\(i\\) 统计独立——单看任一份都不泄露。通信量是两份长 \\(n\\) 的指示向量加两比特答案，即 \\(O(n)\\)；这与平凡下载全集同阶，正是 CGKS 之后研究的起点：多服务器方向用 \\(k\\) 台服务器把通信压到约 \\(n^{1/k}\\) 的亚线性，代价是复制数据库；单服务器计算性 PIR 改用同态加密：在加密查询上算出加密条目，只复制一份，但安全性退到计算性假设。Tor 管网络路径匿名，PIR 藏数据库下标，两者不互相替代。",-1)),a[7]||(a[7]=i("p",null,[i("span",{class:"marginnote"},"单服务器计算性 PIR 由 Kushilevitz and Ostrovsky, FOCS 1997 开创（二次剩余假设）；全同态加密成熟后，PIR 成为 FHE 的直接应用，通信可压到多对数级，代价是数量级的计算与密文膨胀。")],-1)),a[8]||(a[8]=i("p",null,"这两份查询份额到底怎么把 \\(D_i\\) 「挤」出来？",-1)),(l(),t(E,null,{default:e(()=>[n(s,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20U%5B%22%E7%94%A8%E6%88%B7%E6%8A%BD%E9%9A%8F%E6%9C%BA%E9%9B%86%20S%EF%BC%8C%E7%94%9F%E6%88%90%E4%B8%A4%E4%BB%BD%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20S0%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%200%20%E6%94%B6%20S%EF%BC%8C%E5%9B%9E%20X0%22%5D%0A%20%20U%20--%3E%20S1%5B%22%E6%9C%8D%E5%8A%A1%E5%99%A8%201%20%E6%94%B6%20S%20%E5%8A%A0%20i%EF%BC%8C%E5%9B%9E%20X1%22%5D%0A%20%20S0%20--%3E%20X%5B%22%E7%94%A8%E6%88%B7%E6%9C%AC%E5%9C%B0%E7%AE%97%20X0%20%E5%BC%82%E6%88%96%20X1%22%5D%0A%20%20S1%20--%3E%20X%0A%20%20X%20--%3E%20R%5B%22%E6%88%90%E5%AF%B9%E4%B8%8B%E6%A0%87%E5%87%BA%E7%8E%B0%E4%B8%A4%E6%AC%A1%EF%BC%8C%E6%8A%B5%E6%B6%88%E5%90%8E%E5%8F%AA%E5%89%A9%20D_i%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=o('<p><span class="marginnote">数字实例：\\(n=8\\)、\\(i=5\\) 时取 \\(S=\\{1,4,6\\}\\)，则服务器 1 收到 \\(\\{1,4,5,6\\}\\)。\\(X_0=D_1\\oplus D_4\\oplus D_6\\)，\\(X_1=D_1\\oplus D_4\\oplus D_5\\oplus D_6\\)；两者异或时 \\(D_1,D_4,D_6\\) 各出现两次自动抵消，只剩 \\(D_5\\)。</span></p><p><span class="marginnote">常见误区：以为一台服务器也能做到「信息论」保密。CGKS 已证明：单服务器、信息论安全、通信量严格小于下载全集，三者不可兼得。所以单服务器方案必然退到计算性假设——服务器算力够强就能破，多服务器方案则连无限算力也破不了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把实现细节写成利用作业；时间侧信道、恶意服务器返假答案、查询模式关联都在信息论保证之外。Tor 洋葱路由下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>MPC 多方；PIR 用户对库的索引隐私。</li><li>平凡解是下载全部；协议换通信量。</li><li>不替代匿名网络。</li><li>下一课 Tor。</li><li>出处：Chor, Goldreich, Kushilevitz and Sudan, 1998。</li></ul>',6))])}const f=p(B,[["render",u]]);export{S as __pageData,f as default};
